        &lt;ul class="navbar-nav ms-auto gap-2"&gt;
          &lt;li class="nav-item"&gt;&lt;a class="nav-link active" href="index.html"&gt;Países&lt;/a&gt;&lt;/li&gt;
          &lt;li class="nav-item"&gt;&lt;a class="nav-link" href="capital.html"&gt;Consultar Capital&lt;/a&gt;&lt;/li&gt;
